"""Helper utilities."""

def count_vowels(s):
    """Count vowels in s, ignoring case. 'y' counts as a vowel at the end of a word."""
    vowels = set('aeiou')
    count = 0
    s_lower = s.lower()

    for i, char in enumerate(s_lower):
        if char in vowels:
            count += 1
        elif char == 'y':
            # Check if 'y' is at the end of the string or followed by a non-alphabet character
            if i == len(s_lower) - 1 or not s_lower[i + 1].isalpha():
                count += 1

    return count
